function normalizePath(url) {
  return new URL(url).pathname.replace(/\/+$/, "") || "/";
}

function decodeBase64(value) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

async function forwardLead(request) {
  if (request.method !== "POST") {
    return new Response("Method Not Allowed", {
      status: 405,
      headers: { Allow: "POST" }
    });
  }

  const headers = new Headers();
  const contentType = request.headers.get("content-type");
  if (contentType) headers.set("content-type", contentType);
  headers.set("x-forwarded-host", new URL(request.url).host);

  const response = await fetch(LEAD_HANDLER_URL, {
    method: "POST",
    headers,
    body: request.body,
    redirect: "manual"
  });

  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers: {
      "content-type": response.headers.get("content-type") || "application/json; charset=utf-8",
      "cache-control": "no-store"
    }
  });
}

function staticResponse(pathname) {
  const asset = ASSETS[pathname] || ASSETS[pathname + ".html"];
  if (!asset) return new Response("Not found", { status: 404 });
  return new Response(decodeBase64(asset.body), {
    headers: {
      "content-type": asset.type,
      "cache-control": asset.type.startsWith("text/html") ? "no-cache" : "public, max-age=31536000, immutable"
    }
  });
}

export default {
  async fetch(request) {
    const pathname = normalizePath(request.url);
    if (pathname === "/send-lead.php") {
      return forwardLead(request);
    }

    return staticResponse(pathname);
  }
};
